        .RSTRAMB     (1'b0),
        .RSTREGB     (1'b0),
        .WEBWE       ({4{we}}),
        .DIBDI       ({15'b0, din[0]}),
        .DIPBDIP     (2'b0)
    );

    always @(posedge clk) img_sel_q <= img_sel;

    // Επιλογή ποιας εικόνας θα εμφανιστεί στο rgb
    always @(posedge clk) begin
        case (img_sel_q)
            5'd0: rgb = {doaR_1[0], doaG_1[0], doaB_1[0]};
            5'd1: rgb = {doaR_2[0], doaG_2[0], doaB_2[0]};
            5'd2: rgb = {doaR_3[0], doaG_3[0], doaB_3[0]};
            5'd3: rgb = {doaR_4[0], doaG_4[0], doaB_4[0]};
            5'd4: rgb = {doaR_5[0], doaG_5[0], doaB_5[0]};
            5'd5: rgb = {doaR_6[0], doaG_6[0], doaB_6[0]};
            5'd6: rgb = {doaR_7[0], doaG_7[0], doaB_7[0]};
            5'd7: rgb = {doaR_8[0], doaG_8[0], doaB_8[0]};
            5'd8: rgb = {doaR_9[0], doaG_9[0], doaB_9[0]};
            5'd9: rgb = {doaR_10[0], doaG_10[0], doaB_10[0]};
            5'd10: rgb = {doaR_11[0], doaG_11[0], doaB_11[0]};
            5'd11: rgb = {doaR_12[0], doaG_12[0], doaB_12[0]};
            5'd12: rgb = {doaR_13[0], doaG_13[0], doaB_13[0]};
            5'd13: rgb = {doaR_14[0], doaG_14[0], doaB_14[0]};
            5'd14: rgb = {doaR_15[0], doaG_15[0], doaB_15[0]};
            5'd15: rgb = {doaR_16[0], doaG_16[0], doaB_16[0]};
            5'd16: rgb = {doaR_17[0], doaG_17[0], doaB_17[0]};
            5'd17: rgb = {doaR_18[0], doaG_18[0], doaB_18[0]};
            5'd18: rgb = {doaR_19[0], doaG_19[0], doaB_19[0]};
            5'd19: rgb = {doaR_20[0], doaG_20[0], doaB_20[0]};
            5'd20: rgb = {doaR_21[0], doaG_21[0], doaB_21[0]};
            5'd21: rgb = {doaR_22[0], doaG_22[0], doaB_22[0]};
            5'd22: rgb = {doaR_23[0], doaG_23[0], doaB_23[0]};
            default: rgb = 3'b000;
        endcase
    end

endmodule
